import { MessageChannel, moveMessagePortToContext } from 'node:worker_threads';
import { createContext, runInContext } from 'node:vm';
async function main(): Promise<void> {
  const channel = new MessageChannel();
  const port1: any = channel.port1;
  const port2: any = channel.port2;
  const ctx: any = { out: [] as string[], port: undefined as any };
  createContext(ctx);
  ctx.port = moveMessagePortToContext(port1, ctx);
  runInContext(`port.onmessage = function (ev) { out.push([ev.data.constructor === Object, ev.data.list instanceof Array, Object.getPrototypeOf(ev.data) === Object.prototype, this === port, ev.target === port, ev.type, ev.ports.length, typeof MessagePort].join(',')); };`, ctx);
  ctx.port.start();
  port2.postMessage({ list: [1, 2] });
  port2.postMessage({ list: [] });
  for (let i = 0; i < 2000 && ctx.out.length < 2; i++) await new Promise<void>((resolve) => { setTimeout(resolve, 1); });
  console.log(ctx.out.join('|'));
  port2.close();
  ctx.port.close();
}
